          sample: '<p><b>意义</b>：太平天国运动坚持 14 年，势力遍及 18 个省，是中国历史上规模最宏大的一次农民战争。它沉重打击了清朝的统治和外国侵略势力，《资政新篇》还提出了向西方学习、发展资本主义的主张，谱写了近代中国人民反抗压迫、反抗侵略的壮丽篇章。</p><p><b>局限</b>：由于农民阶级的局限性，它提不出切合实际的革命纲领（《天朝田亩制度》的绝对平均主义无法实施），领导集团争权夺利发生天京事变，加上中外反动势力联合镇压，最终失败。</p><p><b>结论</b>：失败不等于没有意义，它说明农民阶级不能单独完成反帝反封建的任务，这一教训同样宝贵。</p>',
