          html: `<p>甲午战争暴露了清政府的腐败无能，列强认为中国已是“一块任人宰割的肥肉”。三国干涉还辽后，列强纷纷在中国<b>强租海港</b>（租借地）、<b>划分势力范围</b>，掀起<b>瓜分中国的狂潮</b>：</p>
<table class="tbl"><tr><th>国家</th><th>租借地</th><th>势力范围</th></tr>
<tr><td>俄国</td><td>旅顺、大连</td><td>长城以北</td></tr>
<tr><td>德国</td><td>胶州湾</td><td>山东</td></tr>
<tr><td>英国</td><td>九龙半岛（“新界”）、威海卫</td><td>长江流域</td></tr>
<tr><td>法国</td><td>广州湾</td><td>广东、广西、云南</td></tr>
<tr><td>日本</td><td>——</td><td><b>福建</b></td></tr></table>
<p>注意最后一行：1898 年，日本迫使清政府承诺不把<b>福建</b>割让或租借给其他国家，福建成了日本的势力范围——我们的家乡也被列强盯上了。</p>
<p><b>美国</b>当时忙于和西班牙打仗，没赶上瓜分。1899 年，美国提出<b>“门户开放”政策</b>：承认各国在中国的势力范围和既得特权，同时要求各国在华“利益均沾”、对美国开放门户。它的实质是美国要分享列强的侵略权益。</p>
<p>当时流传的《时局图》用动物比喻列强：熊代表俄国，犬代表英国，蛙代表法国，太阳代表日本，鹰代表美国——形象地反映了中国面临的瓜分危机。</p>
<div class="key">甲午战败和瓜分狂潮使中国的民族危机空前严重，也促使中国人民觉醒，救亡图存的维新变法运动由此兴起（下一个知识点）。</div>`
