          write: true,
          sample: '<p><b>观点</b>：谭嗣同的牺牲不是“白白牺牲”，但康梁的出走也有其意义，两种选择都体现了爱国。</p><p><b>论述</b>：谭嗣同说“各国变法无不从流血而成”，他希望用自己的鲜血唤醒国人认清顽固派的本质、认识到变法的必要，他的牺牲激励了后来的志士，“我自横刀向天笑”的精神成为宝贵的精神财富。康有为、梁启超逃亡海外后继续办报、著书，宣传维新思想，也推动了思想启蒙。</p><p><b>结论</b>：评价历史人物要看他的行为对历史发展的作用。谭嗣同以死明志，康梁以生续业，都为近代中国的思想解放做出了贡献。</p>',
          checklist: ['观点明确（不只说“各有道理”）', '引用谭嗣同的话或诗句作为史实依据', '说出谭嗣同牺牲的作用（唤醒国人、激励后人）', '说出康梁出走后的活动（继续宣传维新思想）', '结论落到“对历史发展的作用”这一评价标准上', '语言通顺，150 字左右'],
