          h: '义和团运动的兴起与“扶清灭洋”',
          html: `<p>甲午战争后，列强掀起瓜分中国的狂潮，外国传教士和教会势力在中国内地横行，民间反抗情绪越来越强烈。19 世纪末，<b>山东、直隶</b>一带的民间秘密组织<b>义和拳</b>等发展成<b>义和团</b>，成员主要是贫苦农民和手工业者。他们张贴揭帖，号召打击外国侵略者：</p>
<div class="source">神助拳，义和团，只因鬼子闹中原。劝奉教，乃霸天，不敬神佛忘祖先。<span class="from">——义和团揭帖</span></div>
<p>义和团提出的口号是“<b>扶清灭洋</b>”。你要会分析这四个字：</p>
<table class="tbl"><tr><th>口号</th><th>含义</th><th>怎么看</th></tr>
<tr><td>灭洋</td><td>反对外国侵略</td><td>反映了当时<b>民族矛盾</b>是最主要的矛盾，有反帝的正义性；但把一切“洋”的东西（铁路、电线、洋货）都当成打击对象，带有<b>盲目排外</b>的落后性</td></tr>
<tr><td>扶清</td><td>扶助清政府</td><td>说明义和团对清政府的本质认识不清，容易被清政府利用</td></tr></table>
<p>清政府起初镇压义和团，后来看到义和团势力越来越大，又改为“招抚”、利用。1900 年夏，义和团发展到<b>京津地区</b>，运动达到高潮。</p>
<div class="key">义和团运动是一场<b>反帝爱国运动</b>。它沉重打击了帝国主义瓜分中国的野心，也带有盲目排外的局限。</div>`
