        {
          h: '张勋复辟',
          html: `<p>袁世凯死后，又有人想把皇帝请回来。1917 年 6 月，军阀<b>张勋</b>以调解政府内部矛盾为名，率领留着辫子的“<b>辫子军</b>”进入北京。7 月 1 日，他拥戴清朝废帝<b>溥仪</b>复辟。</p>
<p>复辟消息传出，全国一片声讨。孙中山发表讨伐声明，段祺瑞组织“讨逆军”进攻北京。只过了 <b>12 天</b>，复辟就失败了，溥仪再次退位。</p>
<div class="key">袁世凯称帝 83 天、张勋复辟 12 天，两次复辟都迅速失败，从反面证明：民主共和观念深入人心，<b>复辟帝制在中国已经行不通</b>。</div>
<p class="warn">张勋复辟拥戴的是清朝废帝溥仪（宣统帝），不是张勋自己当皇帝；袁世凯则是自己要当“中华帝国”皇帝。两次“复辟”的主角别混。</p>`
        },
        {
          h: '北洋军阀的割据与混战',
          html: `<p>袁世凯死后，他手下的<b>北洋军阀</b>失去了共同的首领，分裂成几个派系，各自依靠不同的帝国主义国家，争夺地盘和中央政权：</p>
<table class="tbl"><tr><th>派系</th><th>首领</th><th>主要势力范围</th><th>依靠的帝国主义</th></tr>
<tr><td><b>直系</b></td><td>冯国璋、曹锟</td><td>江苏、江西、湖北等长江中下游省份</td><td>英、美</td></tr>
<tr><td><b>皖系</b></td><td>段祺瑞</td><td>掌握北京政府，控制安徽、浙江、山东、福建等省</td><td>日本</td></tr>
<tr><td><b>奉系</b></td><td>张作霖</td><td>东北三省</td><td>日本</td></tr></table>
<p>此外，西南还有滇系（唐继尧）、桂系（陆荣廷）等地方军阀。各派军阀为了争夺地盘和中央政权，连年混战。1917 年，孙中山在广州发起<b>护法运动</b>，想依靠西南军阀恢复《临时约法》和国会，结果被军阀排挤，也失败了。</p>
<p>军阀割据混战给人民带来了深重灾难：各派军阀拼命扩充军队，军费开支巨大，苛捐杂税层出不穷；战乱使农田荒芜，工商业凋敝；政局一片混乱。</p>
<div class="key">辛亥革命推翻了帝制，却没有建立起真正的民主共和国。袁世凯独裁、两次复辟、军阀割据，说明<b>资产阶级共和国的方案在半殖民地半封建的中国行不通</b>，先进的中国人还要继续寻找新的出路——这就引出了下一个知识点：新文化运动和五四运动。</div>`
        }
