          write: true,
          sample: '<p>袁世凯复辟帝制失败，根本原因是辛亥革命后民主共和观念已经深入人心，复辟帝制违背历史潮流，遭到全国人民的反对。具体来说：孙中山等革命党人坚决反袁；梁启超等原来支持他的人也公开反对帝制；蔡锷等人在云南发动护国战争，各省纷纷响应；北洋集团内部也有人不愿为他卖命，他众叛亲离。启示：历史潮流不可逆转，谁想开历史倒车，谁就会被人民抛弃。</p>',
