          html: `<p>上一个知识点讲到，井冈山之后，各地农村革命根据地发展起来，其中最大的是以瑞金为中心的<b>中央革命根据地</b>。蒋介石对根据地发动了多次“围剿”。前四次，红军在毛泽东、周恩来、朱德等指挥下都打退了。</p>
<ul class="timeline">
<li><span class="yr">1933 年 9 月</span>蒋介石调集 50 万大军，对中央革命根据地发动第五次“围剿”</li>
<li><span class="yr">1934 年 9 月</span>福建长汀松毛岭战役，红军在中央苏区东线苦战，为主力转移争取了时间；9 月 30 日，红九军团从长汀中复村出发，踏上长征路</li>
<li><span class="yr">1934 年 10 月</span>第五次反“围剿”失利，中共中央和中央红军被迫离开中央革命根据地，开始<b>长征</b></li>
</ul>
<p>第五次反“围剿”为什么会失败？根本原因不是敌人太强，而是当时党中央的负责人<b>博古</b>和军事顾问<b>李德</b>推行“左”倾错误，放弃了前几次反“围剿”中行之有效的游击战、运动战，硬要和敌人打阵地战、“御敌于国门之外”，结果红军损失严重，根据地越打越小。</p>
<div class="key">长征的直接原因：第五次反“围剿”失利；深层原因：博古、李德等人在军事上的“左”倾错误。</div>
<p>福建同学要记住：<b>长汀、宁化</b>都是中央苏区的重要县，也是中央红军长征的出发地之一。1934 年 9 月 30 日，红九军团就是从长汀（中复村）出发踏上长征路的，这里被称为“长征零公里处”。</p>
<p class="warn">“长征”不是主动的战略计划，而是反“围剿”失败后被迫进行的战略转移。出发时间记 1934 年 10 月，出发地记“中央革命根据地（瑞金、长汀等）”。</p>`
