          prompt: '<p>福建长汀是中央苏区的重要县，1934 年 9 月的松毛岭战役后，9 月 30 日红九军团从长汀（中复村）出发踏上长征路，长汀因此被称为“红军长征出发地之一”。</p><p>假如你要向外地同学介绍“长汀与长征”，请写一段 150 字左右的介绍，说清长征为什么开始、长汀在长征中的位置，以及长征最后的结果和意义。</p>',
          write: true,
          sample: '<p>1934 年，由于博古、李德的“左”倾错误，中央红军第五次反“围剿”失利，被迫进行战略转移。我的家乡长汀是中央苏区的重要县，1934 年 9 月红军在松毛岭血战，为主力转移争取了时间；9 月 30 日，红九军团从长汀中复村出发，踏上长征路；10 月，中央红军主力从瑞金等地出发，开始长征。1935 年 1 月的遵义会议挽救了党和红军，此后红军四渡赤水、巧渡金沙江、飞夺泸定桥、翻雪山过草地，1935 年 10 月到达陕北，1936 年 10 月三大主力在会宁会师，长征胜利结束。长征保存了党和红军的基干力量，播下了革命种子，铸就了长征精神。长汀的红色记忆是我们福建人的骄傲。</p>',
          checklist: ['说出长征的直接原因（第五次反“围剿”失利）', '说出长汀是中央苏区重要县、长征出发地之一（松毛岭战役）', '说出长征的时间（1934 年 10 月—1936 年 10 月）', '提到遵义会议的转折作用', '说出长征的意义（保存力量 / 播下种子 / 长征精神，任两点）', '语言通顺，像在向同学介绍'],
