<table class="tbl"><tr><th>中国共产党方面</th><th>国民党方面</th></tr>
<tr><td>中国共产党的正确领导，制定了正确的战略战术（运动战、集中优势兵力各个歼灭）</td><td>发动内战，违背全国人民和平建国的愿望</td></tr>
<tr><td>解放区进行<b>土地改革</b>，广大农民踊跃参军支前，得到<b>人民群众的支持</b></td><td>政治腐败，经济崩溃（通货膨胀），失去民心</td></tr>
<tr><td>人民解放军英勇作战</td><td>军队士气低落</td></tr></table>
